"about_items": [
{
"n": "#5·12",
"text": "This chocolate blazer features a tailored fit with a defined waist, two dark buttons, and structured shoulders. Its deep brown hue and smooth fabric offer a professional yet sophisticated silhouette perfect for an office environment."
},
{
"n": "#135·12",
"text": "The black satin mini skirt has a sleek sheen, delicate lace trim along the hem and side slits for movement. Its high waist and fluid drape create a modern contrast against the structured jacket above."
},
{
"n": "#477·37",
"text": "This black scarf is lightweight and versatile, ready to be worn draped around your neck or styled in various ways to add texture without overpowering the outfit."
},
{
"n": "#369·11",
"text": "These black loafers boast a chunky platform heel and a decorative strap adorned with subtle sparkle. Their smooth leather finish complements the dark tones of your top and skirt perfectly."
},
{
"n": "#46·25",
"text": "A brown raffia tote bag woven from natural fibers, accented with three-dimensional knitted flowers and pearl centers. Its relaxed shape and neutral tone tie together the earthy and black elements of your look."
}
]
